const $=id=>document.getElementById(id), canvas=$('bulletin'),ctx=canvas.getContext('2d');
let geography=null,events=[],selected={id:'demo',place:'Offshore eastern Mindanao',mag:5.2,magType:'Mw',lat:8.2,lon:127.1,depth:32,time:Date.UTC(2026,0,1,0),source:'Illustrative sample · not a real event',origin:'Not specified',notes:'Sample data for preview only. Choose a live event or enter a verified bulletin.',demo:true,url:''},zoom=1,manual=false,busy=false;
const colors={navy:'#17343d',teal:'#19796c',orange:'#e36848',muted:'#6e8588'};
const date=(t,options)=>new Intl.DateTimeFormat('en-PH',{timeZone:'Asia/Manila',...options}).format(new Date(t));
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function text(s,x,y,size=20,color=colors.navy,weight=400){ctx.fillStyle=color;ctx.font=`${weight} ${size}px Arial, sans-serif`;ctx.fillText(s,x,y)}
function wrap(s,x,y,width,size=20,color=colors.navy,weight=400,line=1.4){ctx.font=`${weight} ${size}px Arial`;let words=String(s).split(/\s+/),row='',yy=y;for(let word of words){if(ctx.measureText(row+word).width>width&&row){text(row.trim(),x,yy,size,color,weight);row='';yy+=size*line}row+=word+' '}if(row)text(row.trim(),x,yy,size,color,weight);return yy+size*line}
function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(x,y,w,h)}
function circle(x,y,r,color,stroke){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);if(color){ctx.fillStyle=color;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1.4;ctx.stroke()}}
function draw(){let landscape=$('format').value==='landscape';canvas.width=landscape?1600:1200;canvas.height=landscape?1000:1200;const W=canvas.width,H=canvas.height;rect(0,0,W,H,'#fff');rect(0,0,W,9,colors.teal);text('◎  EPICENTER',48,64,27,colors.teal,700);text('PHILIPPINES  /  EARTHQUAKE INFORMATION',W-660,62,17,colors.muted,500);text(selected.demo?'SAMPLE EARTHQUAKE PLOT':'EARTHQUAKE INFORMATION',48,133,36,colors.navy,700);text(date(selected.time,{day:'2-digit',month:'long',year:'numeric'})+'  •  '+date(selected.time,{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:true})+' PHT (UTC+8)',48,173,19,colors.muted);rect(48,204,W-96,1,'#dbe5e3');
const mx=48,my=238,mw=landscape?960:700,mh=H-365;drawMap(mx,my,mw,mh);let dx=mx+mw+34,dw=W-dx-48;const e=selected;
text('MAGNITUDE',dx,my+20,15,colors.muted,700);text(Number(e.mag).toFixed(1),dx,my+110,85,colors.orange,700);text((e.magType||'M').toUpperCase(),dx+145,my+103,21,colors.muted,600);rect(dx,my+136,dw,1,'#e0e7e4');text('EPICENTER',dx,my+172,14,colors.muted,700);let yy=wrap(e.place,dx,my+208,dw,25,colors.navy,700);yy+=23;text('DEPTH OF FOCUS',dx,yy,14,colors.muted,700);text(Number(e.depth).toFixed(1)+' km',dx,yy+39,30,colors.navy,700);yy+=82;text('COORDINATES',dx,yy,14,colors.muted,700);text(Math.abs(e.lat).toFixed(3)+'° '+(e.lat>=0?'N':'S'),dx,yy+34,21);text(Math.abs(e.lon).toFixed(3)+'° '+(e.lon>=0?'E':'W'),dx,yy+65,21);yy+=108;text('ORIGIN',dx,yy,14,colors.muted,700);text(e.origin||'Not specified',dx,yy+34,21);yy+=77;if(e.notes){text('BULLETIN NOTES',dx,yy,14,colors.muted,700);ctx.save();ctx.beginPath();ctx.rect(dx,yy+12,dw,Math.max(0,my+mh-yy-12));ctx.clip();wrap(e.notes,dx,yy+39,dw,landscape?12:17,colors.muted);ctx.restore()}
rect(48,H-100,W-96,1,'#dbe5e3');text((manual?'MANUAL ENTRY  •  ':'SOURCE  •  ')+e.source,48,H-64,16,colors.muted,600);text('Independent visualization. Refer to PHIVOLCS for official advisories.',48,H-34,15,colors.muted);text('epicenter / PH',W-202,H-34,16,colors.teal,700);}
function drawMap(x,y,w,h){const e=selected,span=14/zoom;let centerLat=zoom===1?12.3:e.lat,centerLon=zoom===1?123:e.lon;let latSpan=span,lonSpan=span*w/h/Math.cos(centerLat*Math.PI/180);const project=(lon,lat)=>[x+w/2+(lon-centerLon)/lonSpan*w,y+h/2-(lat-centerLat)/latSpan*h];ctx.save();ctx.beginPath();ctx.rect(x,y,w,h);ctx.clip();rect(x,y,w,h,'#e9f1f1');
const step=zoom>=3?1:2;ctx.lineWidth=1;ctx.strokeStyle='#d5e2e2';for(let lon=Math.floor(centerLon-lonSpan/2);lon<centerLon+lonSpan/2;lon+=step){let a=project(lon,0)[0];ctx.beginPath();ctx.moveTo(a,y);ctx.lineTo(a,y+h);ctx.stroke();text(lon+'°E',a+5,y+h-12,12,'#93a7a9')}for(let lat=Math.floor(centerLat-latSpan/2);lat<centerLat+latSpan/2;lat+=step){let b=project(0,lat)[1];ctx.beginPath();ctx.moveTo(x,b);ctx.lineTo(x+w,b);ctx.stroke();text(lat+'°N',x+7,b-6,12,'#93a7a9')}
if(geography){for(let f of geography.features){for(let poly of f.geometry.coordinates){ctx.beginPath();for(let ring of poly){ring.forEach(([lon,lat],i)=>{const [a,b]=project(lon,lat);i?ctx.lineTo(a,b):ctx.moveTo(a,b)});ctx.closePath()}ctx.fillStyle='#fdfcf4';ctx.fill('evenodd');ctx.strokeStyle='#a9c3b8';ctx.lineWidth=1.2;ctx.stroke()}}}else{text('Loading geographic basemap…',x+20,y+40,18,colors.muted)}
const labels=[[120.98,14.6,'Manila'],[123.9,10.32,'Cebu'],[125.61,7.08,'Davao'],[122.56,10.72,'Iloilo'],[124.65,8.48,'Cagayan de Oro'],[120.6,16.4,'Baguio'],[122.08,6.92,'Zamboanga'],[118.74,9.74,'Puerto Princesa'],[123.74,13.14,'Legazpi']];for(let [lon,lat,label] of labels){let [a,b]=project(lon,lat);circle(a,b,3,'#8ba79b');text(label,a+7,b+5,14,'#687f78')}
for(let [lon,lat,label] of [[122.1,16.6,'L U Z O N'],[123.4,11.9,'V I S A Y A S'],[125,8.1,'M I N D A N A O']]){let [a,b]=project(lon,lat);text(label,a-55,b-15,13,'#9aaa9d',600)}
for(let item of events){if(item.id===e.id)continue;let[a,b]=project(item.lon,item.lat);circle(a,b,4,'#93aaa099')}
let [a,b]=project(e.lon,e.lat);if(a<x+25||a>x+w-25||b<y+25||b>y+h-25){centerLat=e.lat;centerLon=e.lon;ctx.restore();if(zoom===1){zoom=2;return drawMap(x,y,w,h)}}
for(let r of [65,42,20])circle(a,b,r,r===20?'#e368481a':null,'#e3684855');circle(a,b,8,colors.orange,'#ffffff');ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(a-5,b);ctx.lineTo(a+5,b);ctx.moveTo(a,b-5);ctx.lineTo(a,b+5);ctx.stroke();let lx=Math.min(Math.max(x+12,a+28),x+w-170),ly=Math.min(Math.max(y+45,b-32),y+h-40);rect(lx,ly-23,147,39,'#17343d');text('M '+Number(e.mag).toFixed(1)+'  EPICENTER',lx+11,ly+2,13,'white',700);text('N',x+w-29,y+28,16,colors.navy,700);text('↑',x+w-30,y+52,25,colors.navy);rect(x+17,y+17,selected.demo?140:171,29,'#ffffffdf');text(selected.demo?'ILLUSTRATIVE SAMPLE':'EPICENTER LOCATION',x+27,y+36,11,colors.teal,700);ctx.restore();$('zoomlabel').textContent=zoom===1?'Regional view':zoom+'× detail';}
function renderList(){let filtered=events.filter(e=>e.mag>=Number($('minmag').value));$('count').textContent=filtered.length;$('events').innerHTML=filtered.length?filtered.map(e=>`<button class="event ${e.id===selected.id?'selected':''}" data-id="${escape(e.id)}"><span class="magbox">${Number(e.mag).toFixed(1)}</span><span><strong>${escape(e.place)}</strong><small>${escape(date(e.time,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}))} · ${Math.round(e.depth)} km deep</small></span></button>`).join(''):'<div class="empty">No events to display. Try a longer period, refresh the feed, or use Edit event to enter a verified bulletin.</div>';document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>{selected=events.find(e=>e.id===b.dataset.id);manual=false;zoom=1;renderList();draw()})}
async function refresh(){if(busy)return;busy=true;$('status').textContent='Refreshing USGS data…';try{const start=new Date(Date.now()-Number($('period').value)*86400000).toISOString();const url='https://earthquake.usgs.gov/fdsnws/event/1/query?format=geojson&starttime='+encodeURIComponent(start)+'&minlatitude=4&maxlatitude=22&minlongitude=115&maxlongitude=130&orderby=time&limit=150';const res=await fetch(url,{signal:AbortSignal.timeout(20000)});if(!res.ok)throw Error('Feed returned '+res.status);const data=await res.json();events=data.features.filter(f=>f.properties.mag!=null).map(f=>({id:f.id,place:f.properties.place||'Philippines region',mag:f.properties.mag,magType:f.properties.magType,lon:f.geometry.coordinates[0],lat:f.geometry.coordinates[1],depth:f.geometry.coordinates[2],time:f.properties.time,source:'USGS · '+f.id,origin:'Not specified',notes:'',url:f.properties.url}));if(!manual&&events.length){selected=events.find(e=>e.id===selected.id)||events[0];zoom=1}$('status').textContent='Updated '+date(Date.now(),{hour:'2-digit',minute:'2-digit'})+' PHT · USGS';$('dot').style.color='#177a6c';renderList();draw()}catch(err){$('status').textContent=events.length?'Refresh failed · showing previous data':(manual?'Feed unavailable · manual entry active':'Feed unavailable · sample preview only');$('dot').style.color='#c48a4b';if(!events.length)renderList()}finally{busy=false}}
$('refresh').onclick=refresh;$('period').onchange=refresh;$('minmag').onchange=renderList;$('format').onchange=draw;$('zoomin').onclick=()=>{zoom=Math.min(6,zoom+1);draw()};$('zoomout').onclick=()=>{zoom=Math.max(1,zoom-1);draw()};$('reset').onclick=()=>{zoom=1;draw()};$('previewTab').onclick=()=>$('bulletin').scrollIntoView({behavior:'smooth',block:'center'});
$('save').onclick=()=>{draw();canvas.toBlob(blob=>{if(!blob){$('toast').textContent='Could not create image. Please try again.';return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='epicenter-'+(selected.demo?'sample':selected.id)+'-'+$('format').value+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);$('toast').textContent='Plot saved as PNG · '+canvas.width+' × '+canvas.height},'image/png')};
const form=$('form');function openEditor(){for(let key of ['place','mag','magType','lat','lon','depth','origin','source','notes','url'])form.elements[key].value=selected[key]||'';form.elements.time.value=new Date(selected.time+8*3600000).toISOString().slice(0,19);$('editor').showModal()};$('edit').onclick=openEditor;$('close').onclick=()=>$('editor').close();$('new').onclick=()=>{form.reset();form.elements.source.value='PHIVOLCS (manually entered)';form.elements.time.value=new Date(Date.now()+8*3600000).toISOString().slice(0,19);form.elements.place.focus()};form.onsubmit=ev=>{ev.preventDefault();let data=Object.fromEntries(new FormData(form));for(let k of ['mag','lat','lon','depth'])data[k]=Number(data[k]);data.time=Date.parse(data.time+'+08:00');if(!Number.isFinite(data.time))return;selected={...data,id:'manual-'+Date.now()};manual=true;zoom=1;$('editor').close();renderList();draw();$('toast').textContent='Manual event applied. Verify values against the source before sharing.'};
fetch('countries.json').then(r=>r.json()).then(g=>{geography=g;draw()}).catch(()=>{$('toast').textContent='Basemap could not load. Refresh before exporting.'});draw();refresh();setInterval(refresh,60000);
